// One-off build step: turns the research captures into the files the app uses.
//
//   research/puppies.json + research/happy-families.json + research/assets/mapping.json
//     -> public/puppies/<slug>/NN.ext, public/videos/<slug>-NN.mp4, public/families/NN.ext
//     -> src/data/puppies.ts, src/data/happyFamilies.ts
//
// Run from the project root:  node research/scripts/generate-data.mjs
// The generated files are committed, so you only need this if the research data changes.

import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, extname, join } from "node:path";

const root = join(import.meta.dirname, "..", "..");
const research = join(root, "research");

const puppiesJson = JSON.parse(readFileSync(join(research, "puppies.json"), "utf8"));
const familiesJson = JSON.parse(readFileSync(join(research, "happy-families.json"), "utf8"));
const mapping = JSON.parse(readFileSync(join(research, "assets", "mapping.json"), "utf8"));

// original URL -> local file (relative to research/)
const fileByUrl = new Map(mapping.map((entry) => [entry.url, entry.file]));

/** Copies a captured file into public/ and returns its public URL. */
function copyToPublic(originalUrl, publicPath) {
  const source = fileByUrl.get(originalUrl);
  if (!source) throw new Error(`No downloaded file for ${originalUrl}`);
  const target = join(root, "public", publicPath);
  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(join(research, source), target);
  return `/${publicPath}`;
}

const pad = (n) => String(n).padStart(2, "0");

// ---------- serialiser: readable TypeScript object literals (unquoted keys) ----------

function literal(value, depth = 0) {
  const indent = "  ".repeat(depth);
  const inner = "  ".repeat(depth + 1);
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    const items = value.map((item) => literal(item, depth + 1));
    const oneLine = `[${items.join(", ")}]`;
    if (!oneLine.includes("\n") && oneLine.length <= 90) return oneLine;
    return `[\n${items.map((item) => `${inner}${item},`).join("\n")}\n${indent}]`;
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value).filter(([, v]) => v !== undefined);
    const parts = entries.map(([k, v]) => `${k}: ${literal(v, depth + 1)}`);
    const oneLine = `{ ${parts.join(", ")} }`;
    if (!oneLine.includes("\n") && oneLine.length <= 100) return oneLine;
    return `{\n${parts.map((part) => `${inner}${part},`).join("\n")}\n${indent}}`;
  }
  return JSON.stringify(value);
}

// ---------- puppies ----------

const GENDER_FROM_TEXT = { boy: "male", girl: "female", "boy & girl": "male-female" };

function genderOf(puppy) {
  if (puppy.listing) return puppy.listing.gender;
  // Gone puppies have no listing; the meta description always says "…, girl, 3 months old…"
  const match = puppy.metaDescription.match(/, (boy & girl|boy|girl),/);
  if (!match) throw new Error(`Cannot read gender for ${puppy.slug}`);
  return GENDER_FROM_TEXT[match[1]];
}

function imageOf(media, publicPath) {
  return {
    kind: "image",
    src: copyToPublic(media.url, publicPath),
    width: media.width,
    height: media.height,
    alt: media.alt,
    focalX: media.focalX,
    focalY: media.focalY,
    color: media.color,
  };
}

function mediaOf(slug, media, index) {
  const n = pad(index + 1);
  if (media.kind === "image") {
    return imageOf(media, `puppies/${slug}/${n}${extname(fileByUrl.get(media.url))}`);
  }
  const poster = imageOf(media.poster, `puppies/${slug}/${n}-poster${extname(fileByUrl.get(media.poster.url))}`);
  return {
    kind: "video",
    src: copyToPublic(media.url, `videos/${slug}-${n}.mp4`),
    width: media.width,
    height: media.height,
    alt: media.alt,
    durationS: media.durationS,
    poster,
  };
}

const puppies = puppiesJson.map((puppy) => ({
  slug: puppy.slug,
  name: puppy.name,
  breed: puppy.details.Breed,
  // Filter slugs (maltipoo, poodle, …) exist only for the 15 listed puppies; see types/puppy.ts
  breeds: puppy.listing ? puppy.listing.breeds.map((b) => b.slug) : [],
  gender: genderOf(puppy),
  age: puppy.details.Age,
  colour: puppy.details.Colour,
  origin: puppy.details.Where === "In Dubai" ? "local" : "imported",
  collection: puppy.listing?.collections[0]?.slug,
  status: puppy.gone ? "gone" : "available",
  media: puppy.media.map((media, index) => mediaOf(puppy.slug, media, index)),
}));

const puppiesFile = `// GENERATED by research/scripts/generate-data.mjs from research/puppies.json. Edit the data in place
// only for small fixes; re-running the script overwrites this file.

import type { Puppy } from "@/types/puppy";

/** Every puppy, in the same order as the original site's sitemap. */
export const puppies: Puppy[] = ${literal(puppies)};
`;
writeFileSync(join(root, "src", "data", "puppies.ts"), puppiesFile);

// ---------- happy families ----------

const photos = familiesJson.map((photo, index) => {
  const n = pad(index + 1);
  return {
    src: copyToPublic(photo.url, `families/${n}${extname(fileByUrl.get(photo.url))}`),
    width: photo.width,
    height: photo.height,
    alt: photo.alt,
    caption: photo.caption || undefined,
    focalX: photo.focalX,
    focalY: photo.focalY,
    color: photo.color,
  };
});

const familiesFile = `// GENERATED by research/scripts/generate-data.mjs from research/happy-families.json.

import type { HappyFamilyPhoto } from "@/types/happyFamily";

/** Photos shared by families after taking a puppy home. Only 8 of the 64 have a caption. */
export const happyFamilyPhotos: HappyFamilyPhoto[] = ${literal(photos)};
`;
writeFileSync(join(root, "src", "data", "happyFamilies.ts"), familiesFile);

console.log(`Wrote ${puppies.length} puppies and ${photos.length} family photos.`);
